def is_balanced(s: str) -> bool:
    counter = 0
    for ch in s:
        if ch == '<':
            counter += 1
        elif ch == '>':
            counter -= 1
            if counter < 0:
                return False
        else:
            # ignore other characters if any
            continue
    return counter == 0
