import sys

s = sys.stdin.read()

# Swap case for all letters
swapped = []
for ch in s:
    if ch.isalpha():
        swapped.append(ch.swapcase())
    else:
        swapped.append(ch)
swapped = ''.join(swapped)

# For vowels in the swapped string, advance by two ASCII codes
result = []
for ch in swapped:
    if ch in 'aeiouAEIOU':
        result.append(chr(ord(ch) + 2))
    else:
        result.append(ch)

sys.stdout.write(''.join(result))

class Wallet:
    def __init__(self, initial=0):
        self.balance = initial

    def apply(self, operations):
        for op in operations:
            if isinstance(op, (int, float)):
                self.balance += op
            elif isinstance(op, dict):
                # support {'deposit': x} or {'withdraw': x}
                if 'deposit' in op:
                    self.balance += op['deposit']
                elif 'withdraw' in op:
                    self.balance -= op['withdraw']
            else:
                raise ValueError("Unsupported operation type")

    def is_negative(self):
        return self.balance < 0

def main():
    # Example usage:
    # Start with 0 balance
    wallet = Wallet(0)

    # Define a sequence of operations
    ops = [
        {'deposit': 50},
        -20,
        {'withdraw': 100},
        30,
        {'deposit': 10}
    ]

    wallet.apply(ops)

    print(wallet.balance)
    print(wallet.is_negative())

if __name__ == "__main__":
    main()

